"""Logistic regression model (model.yaml generated by train_model.py): scores warnings, p is the probability of a true issue"""

import math

import yaml

from .features import FEATURES


class Model:
    def __init__(self, path):
        self.path = path
        with open(path, encoding="utf-8") as f:
            data = yaml.safe_load(f) or {}
        self.trained = data.get("trained", "")
        self.params = {c: data[c] for c in FEATURES if c in data}
        for category, m in self.params.items():
            if list(m["features"]) != list(FEATURES[category]):
                raise ValueError(f"{path}: features of '{category}' differ from utils/features.py, "
                                 f"run train_model.py again")

    def score(self, category, features):
        """
        p = sigmoid(intercept + Σ coef * (x - mean) / scale). Returns None (no score) when:
          - there is no model for this check
          - a feature never varies in the training data (min == max) but this warning has a different value: the model
            has never seen such a warning, the score would only be an extrapolation
        """
        m = self.params.get(category)
        if m is None:
            return None
        if any(lo == hi and features[f] != lo for f, lo, hi in zip(m["features"], m.get("min", ()), m.get("max", ()))):
            return None
        z = m["intercept"] + sum(c * (features[f] - mu) / s
                                 for f, c, mu, s in zip(m["features"], m["coef"], m["mean"], m["scale"]))
        return 0.5 * (1.0 + math.tanh(0.5 * z))  # i.e. 1 / (1 + e^-z), does not overflow even for large z
